


clear;
clc;

% Stocks to analyze
stocks = ["AAPL","MSFT","NVDA","AMZN","GOOGL"];


period = "5y";


priceTable = timetable();


for i = 1:length(stocks)

    ticker = stocks(i);

    % Yahoo data 
    url = "https://query1.finance.yahoo.com/v8/finance/chart/" ...
        + ticker + "?range=" + period + "&interval=1d&events=div,splits";

    % Request
    options = weboptions( ...
        'HeaderFields', {'User-Agent','Mozilla/5.0'});

    data = webread(url, options);

    result = data.chart.result(1);

    timestamps = result.timestamp;

    adjustedPrices = result.indicators.adjclose.adjclose;

    % convert timestamps to dates
    dates = datetime(timestamps, ...
        'ConvertFrom','posixtime', ...
        'TimeZone','America/New_York');

    % remove timezone information
    dates.TimeZone = '';

    % Remove missing prices
    valid = ~isnan(adjustedPrices);

    dates = dates(valid);
    adjustedPrices = adjustedPrices(valid);

    % create a timetable for this stock
    newTable = timetable(dates, adjustedPrices, ...
        'VariableNames',{char(ticker)});

    % Combine stock data using matching trading dates
    if i == 1
        priceTable = newTable;
    else
        priceTable = synchronize( ...
            priceTable, newTable, 'intersection');
    end

end


disp(priceTable); %[output:4a8450e8]

% save func
writetimetable(priceTable,'HistoricalStockPrices.csv');
%%
%[text] Calculations for daily returns

priceValues = priceTable.Variables;

% daily percentage returns
dailyReturns = priceValues(2:end,:) ./ ...
    priceValues(1:end-1,:) - 1;


disp('Daily stock returns:'); %[output:4ab4fb2c]
disp(dailyReturns); %[output:27c4e361]
%%
%[text] This is for annualized returns and covariance


% average annualized returns
annualReturns = mean(dailyReturns,1) * 252;

% annualized covariance matrix
annualCovariance = cov(dailyReturns) * 252;


disp('Annualized returns:'); %[output:5fbf7abc]
disp(annualReturns); %[output:0d6ff722]

disp('Annualized covariance matrix:'); %[output:84eeabb2]
disp(annualCovariance); %[output:2cd8c7a3]
%%



figure; %[output:4533f2e0]

plot(priceTable.dates, priceTable.Variables, ... %[output:4533f2e0]
    'LineWidth',1.2); %[output:4533f2e0]

title('Historical Adjusted Stock Prices'); %[output:4533f2e0]
xlabel('Date'); %[output:4533f2e0]
ylabel('Adjusted Price ($)'); %[output:4533f2e0]

legend(stocks,'Location','best'); %[output:4533f2e0]
grid on; %[output:4533f2e0]
%%
%[text] HISTORICAL COMPOUNDED ANNUAL RETURNS

numberOfYears = days(priceTable.dates(end) - ...
    priceTable.dates(1)) / 365.25;

firstPrices = priceTable{1,:};
lastPrices = priceTable{end,:};

CAGR = (lastPrices ./ firstPrices) .^ ...
    (1/numberOfYears) - 1;

disp("Historical Compounded Annual Growth Rates:"); %[output:1d5e40a5]

disp(array2table(CAGR, ... %[output:group:122c48ed] %[output:32ec6c6e]
    'VariableNames',cellstr(stocks))); %[output:group:122c48ed] %[output:32ec6c6e]

